from dataclasses import dataclass

@dataclass
class TaskResult:
    status: str
    result: any = None
    error: str = None
    func: str = None

    @property
    def summary(self):
        return self.status

class TaskRunner:
    def __init__(self):
        self.tasks = []

    def add_task(self, func, *args, **kwargs):
        self.tasks.append((func, args, kwargs))

    def run(self):
        self.results = []
        self.errors = []
        for func, args, kwargs in self.tasks:
            try:
                result = func(*args, **kwargs)
                self.results.append(TaskResult(status='ok', result=result))
            except Exception as e:
                self.errors.append(TaskResult(status='error', error=str(e), func=func.__name__))
        return self.results

    def get_errors(self):
        return [error for result in self.errors if result.error is not None]

    def get_successes(self):
        return [result for result in self.results if result.status == 'ok']
